#!/usr/bin/env bash
# Receives an archive generated by the local setup command on stdin.
set -Eeuo pipefail
umask 077
cd /opt/projects/ai-tools
exec 9>deploy/.deploy.lock
flock -n 9 || { echo '已有部署正在进行，请稍后同步素材。' >&2; exit 1; }
[[ ! -s deploy/current-image ]] || { echo '已有生产部署，首次素材导入已停止。' >&2; exit 1; }
[[ "$(stat -c %u storage/media)" == 1000 && -w storage/media ]] || { echo '上传目录权限不符合 UID 1000 要求。' >&2; exit 1; }
stage=$(mktemp -d "$PWD/deploy/.setup.media.XXXXXX")
cleanup() {
  [[ "$stage" == "$PWD/deploy/.setup.media."* ]] && rm -rf -- "$stage"
}
trap cleanup EXIT
cat > "$stage/media.tar.gz"
tar -tzf "$stage/media.tar.gz" | while IFS= read -r member; do
  member=${member%/}
  case "$member" in media|media/|media/*|media.sha256) ;; *) echo '素材归档包含无效路径。' >&2; exit 1;; esac
  case "/$member/" in */../*|*/./*|*//*) echo '素材归档包含不安全路径。' >&2; exit 1;; esac
done
tar --no-same-owner --no-same-permissions -xzf "$stage/media.tar.gz" -C "$stage"
[[ -z "$(find "$stage/media" -type l -print -quit)" ]] || { echo '素材不允许符号链接。' >&2; exit 1; }
[[ -z "$(find storage/media -type l -print -quit)" ]] || { echo '目标素材目录存在符号链接，已停止。' >&2; exit 1; }
[[ "$(find "$stage/media" -type f | wc -l)" -eq "$(wc -l < "$stage/media.sha256")" ]] || { echo '素材清单数量不一致。' >&2; exit 1; }
(cd "$stage/media" && sha256sum --check ../media.sha256 >/dev/null)
# Check all existing files before adding any new files.
while read -r hash relative; do
  [[ "$hash" =~ ^[a-f0-9]{64}$ && "$relative" =~ ^[a-zA-Z0-9][a-zA-Z0-9._/-]*$ ]] || { echo '素材清单格式无效。' >&2; exit 1; }
  case "/$relative/" in */../*|*/./*|*//*) echo '素材清单路径无效。' >&2; exit 1;; esac
  target="storage/media/$relative"
  if [[ -e "$target" ]]; then
    [[ -f "$target" ]] || { echo '已有素材路径类型冲突。' >&2; exit 1; }
    actual=$(sha256sum -- "$target")
    [[ "${actual%% *}" == "$hash" ]] || { echo '已有同名素材内容不同，保留原文件并停止。' >&2; exit 1; }
  fi
done < "$stage/media.sha256"
while read -r hash relative; do
  target="storage/media/$relative"
  if [[ ! -e "$target" ]]; then
    mkdir -p -- "$(dirname "$target")"
    cp --update=none -- "$stage/media/$relative" "$target"
  fi
done < "$stage/media.sha256"
(cd storage/media && sha256sum --check "$stage/media.sha256" >/dev/null)
echo "首次素材同步和 SHA-256 校验完成：$(wc -l < "$stage/media.sha256") 个文件；已有文件保留。"
